const fs = require("node:fs");
const ts = require("typescript");
const Module = require("node:module");
const source = fs.readFileSync("src/lib/studio.ts", "utf8");
const output = ts.transpileModule(source, {
  compilerOptions: {
    module: ts.ModuleKind.CommonJS,
    target: ts.ScriptTarget.ES2020,
  },
}).outputText;
const moduleObject = new Module("studio-catalog");
moduleObject._compile(output, "studio-catalog.cjs");
const { studio, styles, collections, packages, photos, siteUrl } =
  moduleObject.exports;
fs.writeFileSync(
  "miniprogram/utils/catalog.js",
  "// Generated by scripts/sync-mini-catalog.cjs; prices share the website source.\nmodule.exports = " +
    JSON.stringify(
      {
        studio,
        styles,
        collections,
        packages,
        photos: photos.map((p) => ({ ...p, src: siteUrl + p.src })),
      },
      null,
      2,
    ) +
    ";\n",
);
console.log(
  "Mini program catalogue updated from website prices and collections.",
);
